'use strict';
const http=require('node:http'),fs=require('node:fs'),path=require('node:path');
const files=['css/app.css','js/core/chat-history.js','js/core/chat-search.js','js/core/chat-read-model.js','js/core/chat-header-model.js','js/core/operational-read-model.js','js/modules/purchase-order-search.v1.js','js/modules/purchase-orders.js'];
const html=`<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/css/app.css"><style>body{margin:0;padding:18px;background:#0b1321;color:#e7eefb}main{max-width:1200px;margin:auto}h1{font-size:23px}#chat-messages{max-height:400px;overflow:auto}.page.active{display:block!important}.demo-card{padding:18px;background:#142137;border:1px solid #344963;border-radius:14px;margin:18px 0}.demo-actions{display:flex;gap:10px;flex-wrap:wrap}#chat-buscar{width:100%;padding:12px;background:#1b2b45;color:white;border:1px solid #405577;border-radius:8px}</style><body class="dark-mode"><main><h1>Chat y Compras · ejemplo local</h1><p>Sólo datos ficticios. Guardados deshabilitados; sin conexión con Firebase.</p><section class="demo-card"><h2>Chat</h2><p>75 mensajes iniciales. Buscá «histórico» para encontrar también los anteriores.</p><input id="chat-buscar" aria-label="Buscar mensaje" placeholder="Buscar mensaje" oninput="SVChatSearch.search()"><div id="chat-messages"></div><div class="demo-actions"><button class="btn" onclick="_chatHistory.older()">Ver anteriores</button><span id="demo-reads" role="status"></span></div></section><div class="page active" id="page-ordenes"></div><div class="page" id="page-balancecompra"></div></main>
<script>
const bodies=Object.fromEntries(Array.from({length:120},(_,i)=>['m'+String(i).padStart(3,'0'),{autor:'Persona ficticia',autorUid:'other',texto:'Mensaje histórico '+i,ts:i+1}]));let headers,reads=0;
window.currentUserUid='fixture';window.currentRole='admin';window.fbAuth={currentUser:{uid:'fixture'}};window.fbDB={};window._chatCanal='general';window._chatCargaId=0;window._chatListener=null;window._chatListaVisible=[];window._chatHistory=null;
window.escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));window.chatPuedeAccederCanal=()=>true;window.chatEstaLeyendo=()=>true;window.chatNombreSesion=()=> 'Ejemplo';window._chatFueLeido=()=>true;window.notify=message=>document.getElementById('demo-reads').textContent=message;window.chatHeadersSnapshot=()=>headers;
window.fbRef=(_,p)=>p;window.fbOrderByChild=field=>({field});window.fbLimitToLast=limit=>({limit});window.fbEndBefore=(ts,key)=>({before:ts,key});window.fbQuery=(path,...constraints)=>({path,...Object.assign({},...constraints)});window.fbSet=window.fbUpdate=window.fbRemove=()=>{throw Error('Este ejemplo no guarda datos');};
function snapshot(query){if(typeof query==='string'){if(query.startsWith('sv_chat/general/'))return bodies[query.split('/').at(-1)];throw Error('Lectura de raíz completa prohibida');}if(query.path!=='sv_chat/general'||!query.limit)throw Error('Consulta sin límite prohibida');return Object.fromEntries(Object.entries(bodies).filter(([key,m])=>query.before==null||m.ts<query.before||m.ts===query.before&&key<query.key).slice(-query.limit));}
window.fbOnValue=(query,next)=>{reads++;next({val:()=>snapshot(query)});return()=>{};};window.fbGet=async query=>({val:()=>snapshot(query)});window.chatRenderMensajes=rows=>{window._chatListaVisible=rows;document.getElementById('chat-messages').innerHTML=rows.map(m=>'<p><b>'+escapeHTML(m.autor)+'</b><br>'+escapeHTML(m.texto)+'</p>').join('');document.getElementById('demo-reads').textContent=rows.length+' mensajes cargados · '+reads+' consultas acotadas';};window.permisoModulo=()=>true;
</script>${files.filter(f=>f.endsWith('.js')).map(f=>'<script src="/'+f+'"></script>').join('')}
<script>
headers=Object.fromEntries(Object.entries(bodies).map(([key,m])=>[key,SVChatHeaderModel.chat(m)]));
window.chatCargarCanal=()=>{_chatListener?.();_chatHistory=SVChatHistory.watch('general',(snapshot,status)=>{if(status.statusOnly)return;chatRenderMensajes(Object.entries(snapshot.val()).map(([fbKey,m])=>({fbKey,...m})));},notify);_chatListener=()=>_chatHistory.stop();};chatCargarCanal();
const state=SisVentasCompras.state;state.loaded={ordenes:true,listas_materiales:true,inventario_operativo:true};state.orders=Array.from({length:123},(_,i)=>({fbKey:'o'+i,numero:'OC-FICTICIA-'+i,fecha:'2026-10-01',estado:'recibida',total:10,items:[{codigo:'P-'+i,descripcion:'Material ficticio '+i,cantidadOrdenada:2,cantidadRecibida:2}]}));state.lists=[];SisVentasCompras.renderAll();
</script></body></html>`;
async function start(port=0){const root=path.resolve(__dirname,'../..'),server=http.createServer((req,res)=>{const name=new URL(req.url,'http://127.0.0.1').pathname.slice(1);if(!name){res.setHeader('Content-Type','text/html; charset=utf-8');res.end(html);return;}if(!files.includes(name)){res.writeHead(404).end();return;}res.setHeader('Content-Type',name.endsWith('.css')?'text/css':'application/javascript');res.end(fs.readFileSync(path.join(root,name)));});await new Promise(r=>server.listen(port,'127.0.0.1',r));return {server,url:'http://127.0.0.1:'+server.address().port+'/'};}
module.exports={start};if(require.main===module)start(Number(process.argv[2])||0).then(s=>console.log(s.url));
